query FindOneCompany($objectRecordId: UUID!) {
  company(filter: {id: {eq: $objectRecordId}}) {
    __typename
    accountOwner {
      __typename
      avatarUrl
      id
      name {
        firstName
        lastName
        __typename
      }
    }
    accountOwnerId
    address {
      addressStreet1
      addressStreet2
      addressCity
      addressState
      addressCountry
      addressPostcode
      addressLat
      addressLng
      __typename
    }
    agentChatThreadTargets {
      edges {
        node {
          __typename
          id
          thread {
            __typename
            id
            title
          }
        }
        __typename
      }
      __typename
    }
    annualRevenue {
      amountMicros
      currencyCode
      __typename
    }
    attachments {
      edges {
        node {
          __typename
          id
          name
        }
        __typename
      }
      __typename
    }
    calendarEventTargets {
      edges {
        node {
          __typename
          calendarEvent {
            __typename
            id
            title
          }
          id
        }
        __typename
      }
      __typename
    }
    createdAt
    createdBy {
      source
      workspaceMemberId
      name
      context {
        provider
        applicationId
        __typename
      }
      __typename
    }
    deletedAt
    domainName {
      primaryLinkUrl
      primaryLinkLabel
      secondaryLinks {
        label
        url
        __typename
      }
      __typename
    }
    id
    linkedinLink {
      primaryLinkUrl
      primaryLinkLabel
      secondaryLinks {
        label
        url
        __typename
      }
      __typename
    }
    messageThreadTargets {
      edges {
        node {
          __typename
          id
          messageThread {
            __typename
            id
            subject
          }
        }
        __typename
      }
      __typename
    }
    name
    noteTargets {
      edges {
        node {
          __typename
          id
          note {
            __typename
            id
            title
          }
        }
        __typename
      }
      __typename
    }
    opportunities {
      edges {
        node {
          __typename
          id
          name
        }
        __typename
      }
      __typename
    }
    people {
      edges {
        node {
          __typename
          avatarFile {
            fileId
            label
            extension
            url
            __typename
          }
          id
          name {
            firstName
            lastName
            __typename
          }
        }
        __typename
      }
      __typename
    }
    position
    taskTargets {
      edges {
        node {
          __typename
          id
          task {
            __typename
            id
            title
          }
        }
        __typename
      }
      __typename
    }
    timelineActivities {
      edges {
        node {
          __typename
          id
          linkedRecordCachedName
        }
        __typename
      }
      __typename
    }
    updatedAt
    updatedBy {
      source
      workspaceMemberId
      name
      context {
        provider
        applicationId
        __typename
      }
      __typename
    }
  }
}
